<!--This File Is Generated By AI-->

<script setup lang="ts">
import {onMounted, type Ref, ref} from "vue"
import NProgress from 'nprogress'
import {AnimatePresence, Motion} from "motion-v";
import api from "@/api/http.ts";
import {useToast} from "@/composables/message.ts";
import type {
    DtoCommentDto,
    DtoLocationDto,
    ResponseAdminStatusResponse,
} from "@/api/api";
import {
    AnimateIcon,
    ArrowLeft,
    CalendarDays,
    CircleCheck,
    CircleX,
    CookingPot,
    LayoutDashboard,
    LoaderCircle,
    MapPin,
    MessageSquare,
    RefreshCcw,
    ShieldCheck,
    Star,
    Users,
} from '@respeak/lucide-motion-vue'
import {useRouter} from "vue-router"

type AdminTab = 'dashboard' | 'comments' | 'locations'

interface AdminNavItem {
    key: AdminTab
    label: string
    description: string
    icon: any
}

const toast = useToast()
const router = useRouter()

const PAGE_SIZE = 10

const activeTab: Ref<AdminTab> = ref('dashboard')
const loading = ref(false)

const status: Ref<ResponseAdminStatusResponse | null> = ref(null)
const comments: Ref<DtoCommentDto[]> = ref([])
const locations: Ref<DtoLocationDto[]> = ref([])

const commentsHasNext = ref(false)
const commentsLoading = ref(false)
const commentReviewing = ref<Set<number>>(new Set())

const locationsHasNext = ref(false)
const locationsLoading = ref(false)
const locationReviewing = ref<Set<number>>(new Set())

const navItems: AdminNavItem[] = [
    {key: 'dashboard', label: '概览', description: '应用运行状态', icon: LayoutDashboard},
    {key: 'comments', label: '评论审核', description: '待审核的评论', icon: MessageSquare},
    {key: 'locations', label: '地点审核', description: '待审核的地点', icon: MapPin},
]

function formatTime(value?: string): string {
    if (!value) return "-"
    const date = new Date(value)
    if (Number.isNaN(date.getTime())) return value
    return date.toLocaleString('zh-CN', {
        year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit',
    })
}

async function loadStatus() {
    try {
        const resp = await api.admin.statusList()
        if (resp.data.code !== 0) {
            toast.error("加载状态失败: " + resp.data.message)
            return
        }
        status.value = resp.data.data ?? null
    } catch (e) {
        toast.error("加载状态失败: 服务器错误")
    }
}

async function loadComments(reset = true) {
    if (commentsLoading.value) return
    commentsLoading.value = true
    try {
        const query = reset || comments.value.length === 0
            ? {page_size: PAGE_SIZE}
            : {page_size: PAGE_SIZE, start_id: comments.value[comments.value.length - 1]?.id}
        const resp = await api.admin.commentsList(query)
        if (resp.data.code !== 0) {
            toast.error("加载评论失败: " + resp.data.message)
            return
        }
        const data = resp.data.data
        if (reset) comments.value.length = 0
        comments.value.push(...(data?.comments ?? []))
        commentsHasNext.value = data?.has_next ?? false
    } catch (e) {
        toast.error("加载评论失败: 服务器错误")
    } finally {
        commentsLoading.value = false
    }
}

async function loadLocations(reset = true) {
    if (locationsLoading.value) return
    locationsLoading.value = true
    try {
        const query = reset || locations.value.length === 0
            ? {page_size: PAGE_SIZE}
            : {page_size: PAGE_SIZE, start_id: locations.value[locations.value.length - 1]?.id}
        const resp = await api.admin.locationsList(query)
        if (resp.data.code !== 0) {
            toast.error("加载地点失败: " + resp.data.message)
            return
        }
        const data = resp.data.data
        if (reset) locations.value.length = 0
        locations.value.push(...(data?.locations ?? []))
        locationsHasNext.value = data?.has_next ?? false
    } catch (e) {
        toast.error("加载地点失败: 服务器错误")
    } finally {
        locationsLoading.value = false
    }
}

async function reviewComment(comment: DtoCommentDto, pass: boolean) {
    const id = comment.id ?? 0
    if (!id || commentReviewing.value.has(id)) return
    commentReviewing.value.add(id)
    try {
        const resp = await api.admin.commentsIdPartialUpdate(id, {pass})
        if (resp.data.code !== 0) {
            toast.error("审核失败: " + resp.data.message)
            return
        }
        toast.success(pass ? "评论已通过" : "评论已驳回")
        comments.value = comments.value.filter(c => c.id !== id)
    } catch (e) {
        toast.error("审核失败: 服务器错误")
    } finally {
        commentReviewing.value.delete(id)
    }
}

async function reviewLocation(location: DtoLocationDto, pass: boolean) {
    const id = location.id ?? 0
    if (!id || locationReviewing.value.has(id)) return
    locationReviewing.value.add(id)
    try {
        const resp = await api.admin.locationsIdPartialUpdate(id, {pass})
        if (resp.data.code !== 0) {
            toast.error("审核失败: " + resp.data.message)
            return
        }
        toast.success(pass ? "地点已通过" : "地点已驳回")
        locations.value = locations.value.filter(l => l.id !== id)
    } catch (e) {
        toast.error("审核失败: 服务器错误")
    } finally {
        locationReviewing.value.delete(id)
    }
}

async function onRefresh() {
    loading.value = true
    if (activeTab.value === 'dashboard') await loadStatus()
    else if (activeTab.value === 'comments') await loadComments(true)
    else await loadLocations(true)
    loading.value = false
}

function switchTab(tab: AdminTab) {
    activeTab.value = tab
}

onMounted(async () => {
    NProgress.done()
    await Promise.all([loadStatus(), loadComments(true), loadLocations(true)])
})
</script>

<template>
    <div class="relative flex h-full w-full bg-blue-50">
        <aside class="flex w-64 shrink-0 flex-col border-r border-gray-100 bg-white shadow-2xl">
            <div class="flex items-center gap-3 px-5 py-6">
                <div class="flex h-11 w-11 items-center justify-center rounded-2xl bg-blue-400 shadow">
                    <AnimateIcon animateOnHover triggerTarget="parent">
                        <ShieldCheck class="text-white" :size="24"/>
                    </AnimateIcon>
                </div>
                <div class="flex flex-col leading-tight">
                    <span class="text-lg font-bold text-gray-800">管理后台</span>
                    <span class="text-xs text-gray-400">RiceRise Admin</span>
                </div>
            </div>

            <nav class="flex flex-col space-y-1 px-3">
                <button
                    v-for="item in navItems"
