                >
                    <AnimateIcon animateOnHover triggerTarget="parent">
                        <component :is="item.icon" :size="20"/>
                    </AnimateIcon>
                    <span class="flex flex-col">
                        <span class="font-medium">{{ item.label }}</span>
                        <span
                            class="text-xs"
                            :class="activeTab === item.key ? 'text-blue-50' : 'text-gray-400'"
                        >{{ item.description }}</span>
                    </span>
                </button>
            </nav>

            <div class="mt-auto p-3">
                <button
                    @click="async () => await router.replace({name: 'home'})"
                    class="flex w-full items-center justify-center gap-2 rounded-2xl border border-gray-200 px-3 py-3 text-gray-600 transition-colors hover:bg-blue-400 hover:text-white"
                >
                    <AnimateIcon animateOnHover triggerTarget="parent">
                        <ArrowLeft :size="18"/>
                    </AnimateIcon>
                    返回主页
                </button>
            </div>
        </aside>

        <main class="relative flex-1 overflow-hidden">
            <header class="flex items-center justify-between px-8 py-6">
                <div class="flex flex-col">
                    <h1 class="text-2xl font-bold text-gray-800">
                        {{ navItems.find(i => i.key === activeTab)?.label }}
                    </h1>
                    <span class="text-sm text-gray-500">
                        {{ navItems.find(i => i.key === activeTab)?.description }}
                    </span>
                </div>
                <button
                    @click="onRefresh"
                    class="flex h-11 w-11 items-center justify-center rounded-full bg-white text-gray-500 shadow transition-colors hover:bg-blue-400 hover:text-white"
                >
                    <AnimateIcon animateOnHover triggerTarget="parent">
                        <RefreshCcw :size="20" :class="{'animate-spin': loading}"/>
                    </AnimateIcon>
                </button>
            </header>

            <section class="h-[calc(100%-6rem)] overflow-y-auto px-8 pb-8">
                <AnimatePresence mode="wait">
                    <Motion
                        :key="activeTab"
                        :initial="{opacity: 0, y: 12}"
                        :animate="{opacity: 1, y: 0}"
                        :exit="{opacity: 0, y: -12}"
                        :transition="{duration: 0.2, ease: 'easeOut'}"
                        class="h-full"
                    >
                        <template v-if="activeTab === 'dashboard'">
                            <div class="grid grid-cols-2 gap-5 xl:grid-cols-4">
                                <div class="flex flex-col rounded-2xl bg-white p-5 shadow-lg">
                                    <div class="flex items-center justify-between">
                                        <span class="text-sm text-gray-500">总用户数</span>
                                        <Users class="text-blue-400" :size="20"/>
                                    </div>
                                    <span class="mt-2 text-3xl font-bold text-gray-800">{{ status?.total_user ?? '-' }}</span>
                                </div>
                                <div class="flex flex-col rounded-2xl bg-white p-5 shadow-lg">
                                    <div class="flex items-center justify-between">
                                        <span class="text-sm text-gray-500">总地点数</span>
                                        <MapPin class="text-blue-400" :size="20"/>
                                    </div>
                                    <span class="mt-2 text-3xl font-bold text-gray-800">{{ status?.total_location ?? '-' }}</span>
                                </div>
                                <div class="flex flex-col rounded-2xl bg-white p-5 shadow-lg">
                                    <div class="flex items-center justify-between">
                                        <span class="text-sm text-gray-500">总饭局数</span>
                                        <CalendarDays class="text-blue-400" :size="20"/>
                                    </div>
                                    <span class="mt-2 text-3xl font-bold text-gray-800">{{ status?.total_dinner ?? '-' }}</span>
                                </div>
                                <div class="flex flex-col rounded-2xl bg-white p-5 shadow-lg">
                                    <div class="flex items-center justify-between">
                                        <span class="text-sm text-gray-500">进行中饭局</span>
                                        <CookingPot class="text-blue-400" :size="20"/>
                                    </div>
                                    <span class="mt-2 text-3xl font-bold text-gray-800">{{ status?.current_dinner ?? '-' }}</span>
                                </div>
                            </div>

                            <div class="mt-5 grid grid-cols-2 gap-5">
                                <div class="flex flex-col rounded-2xl bg-white p-6 shadow-lg">
                                    <h2 class="text-lg font-bold text-gray-800">待审核评论</h2>
                                    <p class="mt-1 text-sm text-gray-500">{{ comments.length }} 条待处理</p>
                                    <button
                                        @click="switchTab('comments')"
                                        class="mt-4 self-start rounded-lg border border-gray-200 px-4 py-2 text-sm transition-colors hover:bg-blue-400 hover:text-white"
                                    >前往审核</button>
                                </div>
                                <div class="flex flex-col rounded-2xl bg-white p-6 shadow-lg">
                                    <h2 class="text-lg font-bold text-gray-800">待审核地点</h2>
                                    <p class="mt-1 text-sm text-gray-500">{{ locations.length }} 个待处理</p>
                                    <button
                                        @click="switchTab('locations')"
                                        class="mt-4 self-start rounded-lg border border-gray-200 px-4 py-2 text-sm transition-colors hover:bg-blue-400 hover:text-white"
                                    >前往审核</button>
                                </div>
                            </div>
                        </template>

                        <template v-else-if="activeTab === 'comments'">
                            <div class="flex flex-col space-y-3">
                                <AnimatePresence>
                                <Motion
                                    v-for="comment in comments"
                                    :key="comment.id"
                                    layout
                                    :initial="{opacity: 0, x: 30}"
                                    :animate="{opacity: 1, x: 0}"
                                    :exit="{opacity: 0, x: -30}"
                                    :transition="{type: 'spring', stiffness: 300, damping: 30}"
                                    class="flex flex-col rounded-2xl bg-white p-5 shadow-lg"
                                >
                                    <div class="flex items-start justify-between">
                                        <div class="flex flex-col">
                                            <span class="font-bold text-gray-800">{{ comment.user?.nickname ?? '匿名用户' }}</span>
                                            <span class="text-xs text-gray-400">@ {{ comment.user?.username ?? '-' }}</span>
                                        </div>
                                        <div class="flex items-center space-x-0.5">
                                            <Star
                                                v-for="n in 5"
                                                :key="n"
                                                :size="16"
                                                :class="n <= (comment.rating ?? 0) ? 'text-yellow-400' : 'text-gray-200'"
                                                :fill="n <= (comment.rating ?? 0) ? 'currentColor' : 'none'"
                                            />
                                        </div>
                                    </div>
                                    <p class="mt-3 text-gray-700">{{ comment.content }}</p>
                                    <div class="mt-3 flex items-center gap-2 text-xs text-gray-400">
                                        <MapPin :size="14"/>
                                        <span>{{ comment.location?.name ?? '未知地点' }}</span>
                                        <span>·</span>
                                        <span>{{ formatTime(comment.createdAt) }}</span>
                                    </div>
                                    <div class="mt-4 flex space-x-2">
                                        <button
                                            @click="async () => await reviewComment(comment, true)"
                                            :disabled="commentReviewing.has(comment.id ?? 0)"
                                            class="flex flex-1 items-center justify-center gap-2 rounded-lg bg-blue-400 py-2 text-white shadow transition-colors hover:brightness-90 disabled:opacity-50"
                                        >
                                            <AnimateIcon animateOnHover triggerTarget="parent">
                                                <CircleCheck :size="18"/>
                                            </AnimateIcon>
                                            通过
                                        </button>
                                        <button
                                            @click="async () => await reviewComment(comment, false)"
                                            :disabled="commentReviewing.has(comment.id ?? 0)"
                                            class="flex flex-1 items-center justify-center gap-2 rounded-lg bg-white py-2 text-gray-600 shadow transition-colors hover:bg-red-400 hover:text-white disabled:opacity-50"
                                        >
                                            <AnimateIcon animateOnHover triggerTarget="parent">
                                                <CircleX :size="18"/>
                                            </AnimateIcon>
                                            驳回
                                        </button>
                                    </div>
                                </Motion>
                                </AnimatePresence>

                                <span v-if="comments.length === 0 && !commentsLoading" class="py-20 text-center text-sm text-gray-500">
                                    当前暂无待审核评论...
                                </span>
                                <button
                                    v-if="commentsHasNext"
                                    @click="loadComments(false)"
                                    :disabled="commentsLoading"
                                    class="flex items-center justify-center gap-2 rounded-2xl border border-gray-200 bg-white py-3 text-sm text-gray-600 shadow transition-colors hover:bg-blue-400 hover:text-white disabled:opacity-50"
                                >
                                    <LoaderCircle v-if="commentsLoading" class="animate-spin" :size="16"/>
                                    加载更多
                                </button>
                            </div>
                        </template>

                        <template v-else>
                            <div class="flex flex-col space-y-3">
                                <AnimatePresence>
                                <Motion
                                    v-for="location in locations"
                                    :key="location.id"
                                    layout
                                    :initial="{opacity: 0, x: 30}"
                                    :animate="{opacity: 1, x: 0}"
                                    :exit="{opacity: 0, x: -30}"
                                    :transition="{type: 'spring', stiffness: 300, damping: 30}"
                                    class="flex flex-col rounded-2xl bg-white p-5 shadow-lg"
                                >
                                    <div class="flex items-start justify-between">
                                        <div class="flex flex-col">
                                            <span class="text-lg font-bold text-gray-800">{{ location.name }}</span>
                                            <span class="text-sm text-gray-500">{{ location.address }}</span>
                                        </div>
                                        <span class="rounded-full bg-blue-50 px-3 py-1 text-xs text-blue-500">待审核</span>
                                    </div>
                                    <p class="mt-3 text-gray-700">{{ location.description }}</p>
                                    <div class="mt-3 flex items-center gap-2 text-xs text-gray-400">
                                        <MapPin :size="14"/>
                                        <span>{{ location.latitude?.toFixed(5) }}, {{ location.longitude?.toFixed(5) }}</span>
