                                        >
                                            <AnimateIcon animateOnHover triggerTarget="parent">
                                                <CircleCheck :size="18"/>
                                            </AnimateIcon>
                                            通过
                                        </button>
                                        <button
                                            @click="async () => await reviewLocation(location, false)"
                                            :disabled="locationReviewing.has(location.id ?? 0)"
                                            class="flex flex-1 items-center justify-center gap-2 rounded-lg bg-white py-2 text-gray-600 shadow transition-colors hover:bg-red-400 hover:text-white disabled:opacity-50"
                                        >
                                            <AnimateIcon animateOnHover triggerTarget="parent">
